/* =========================================================
   v3.0 元素素材库 + 全量元素表（365 只按 5 只示例的方向重构）
   · 元素图元：0~1 归一化方框里的路径，按部件框等比缩放；颜色取精灵自己的三色（c 主色 / a 强调色 / l 浅色），主色 ≤ 3
   · 部件挂点：按本体实际外框（getBBox）计算 top / L / R / LR / tail / base / belly / back / orb / hold
   · 特效库：LV3 伙伴队形 7 种 · LV4 质变 8 类 × 3 变体 · LV5 法相 7 种 · 本体纹样 16 种
   · 每只精灵一行元素表：本体 / 部件 A / 部件 B / 伙伴（= LV1 破口元素）/ 核心徽记，三色，纹样，队形，质变变体，法相
   · 唯一性校验：任意两只元素组合不同；同类任意两只至少 4 项不同
   · 精灵画面不出现文字
========================================================= */
/* ---------- 归一化路径 → 部件框 ---------- */
function spNP(d, x0, y, w, h){
  const t = String(d).match(/[A-Za-z]|-?\d*\.?\d+/g) || []; let o = '', cmd = '', i = 0;
  const X = u=>spF(x0 + (u - .5)*w), Y = v=>spF(y + v*h);
  while(i < t.length){ const tk = t[i];
    if(/[A-Za-z]/.test(tk)){ cmd = tk; o += tk; i++; continue; }
    if(cmd==='H'){ o += X(+tk) + ' '; i++; }
    else if(cmd==='V'){ o += Y(+tk) + ' '; i++; }
    else if(cmd==='A'){ const a = t.slice(i, i + 7).map(Number); o += `${spF(a[0]*w)} ${spF(a[1]*h)} ${a[2]} ${a[3]} ${a[4]} ${X(a[5])} ${Y(a[6])} `; i += 7; }
    else { o += X(+tk) + ' ' + Y(+t[i + 1]) + ' '; i += 2; }
  }
  return o.trim();
}
